const nombre = prompt("Tu nombre");
const meta = prompt("Tu meta");
const textoMinutos = prompt("Minutos diarios");
const minutos = Number(textoMinutos);
const textoDias = prompt("Días del plan");
const dias = Number(textoDias);
const referencia = 20;
if (textoMinutos.trim() !== "" && Number.isInteger(minutos) && minutos >= 0 && minutos <= 120 && textoDias.trim() !== "" && Number.isInteger(dias) && dias >= 0 && dias <= 7) {
  const total = minutos * dias;
  const minutosAmpliados = minutos + 5;
  const totalAmpliado = minutosAmpliados * dias;
  const tipoMinutos = typeof minutos;
  let recomendacion;
  if (minutos >= 60) { recomendacion = "Intensivo"; }
  else {
    if (minutos >= 30) { recomendacion = "Constante"; }
    else { recomendacion = "Inicio"; }
  }
  console.log("Hola TeslaCode");
  console.log("Mi plan de práctica");
  console.log("Estado: listo");
  console.log("Sesión: JavaScript");
  console.log("Minutos diarios:", minutos);
  console.log("Días:", dias);
  console.log("Meta:", meta);
  console.log("Recordatorio:", meta);
  console.log("Referencia diaria:", referencia);
  console.log("Total:", total);
  console.log("Nombre:", nombre);
  console.log("Plan con 5 más:", totalAmpliado);
  console.log("Tipo de minutos:", tipoMinutos);
  console.log("Horas previstas:", total / 60);
  console.log("Resto de 10:", minutos % 10);
  console.log("Disponible hasta 120:", 120 - minutos);
  console.log("Alcanza 30:", minutos >= 30);
  console.log("Igual a referencia:", minutos === referencia);
  console.log("Distinto de referencia:", minutos !== referencia);
  console.log("Recomendación:", recomendacion);
  console.log("Sesiones programadas:", dias);
  let paso = 1;
  while (paso <= dias) {
    console.log("Día:", paso);
    paso = paso + 1;
  }
} else { console.log("Entrada inválida"); }

